+		callsSinceFlush++
+		if attempt.Err == nil {
+			if err := storeResults(attempt.Results); err != nil {
+				return nil, err
+			}
+			anyProviderSuccess = true
+			packCompleted++
+			if err := flushCache(false); err != nil {
+				return nil, err
+			}
+			continue
+		}
